use moloch_live_runtime::relationship_census::{self,Availability,Census,CensusCache,CensusReport,SourceEvidence,Surface};
#[path="../src/relationship_strategy.rs"] mod strategy;
use strategy::*;
use baal_transport_service::{Receipt,Scope,relationships};
use moloch_relationship_arbitrage::{Book,Level,Side,Source,UNIT};
use serde_json::json;
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},path::PathBuf};

const T:&str="bda92870-621e-47b0-bc3c-3602c5c26f55";
const R:&str="00000000-0000-4000-8000-000000000124";
const AT:&str="2026-10-15T09:01:00.000Z";
fn now()->u64{chrono::DateTime::parse_from_rfc3339(AT).unwrap().timestamp_millis() as u64}
fn receipt(endpoint:String,data:serde_json::Value)->Receipt{Receipt{endpoint,request_started_at:AT.into(),received_at:AT.into(),status:200,data}}
fn level(p:i128)->Vec<Level>{vec![Level{price:p,quantity:100}]}
fn surface()->Surface{Surface{availability:Availability::NotRequested,row_count:None,source:None,error_code:None,http_status:None,retry_after_ms:None}}
struct Fixture{census:Census,canonical:Receipt,certs:Vec<SettlementCertificate>,trusted:BTreeSet<String>,rules:Vec<Receipt>,books:BTreeMap<String,Book>,policy:Policy,capital:Capital}
impl Fixture{
 fn analyze(&self,positions:&[OwnedPosition])->Analysis{analyze(&self.census,&self.canonical,&Certificates{values:&self.certs,trusted_sha256:&self.trusted,rule_receipts:&self.rules},&self.books,positions,&self.capital,&self.policy)}
 fn approve(&mut self){self.trusted=self.certs.iter().map(|c|certificate_sha256(c).unwrap()).collect();}
}
fn fixture(n:usize,exhaustive:bool)->Fixture{
 let scope=Scope{tournament_id:T.into(),tournament_slug:"midterm-elections".into(),exchanges:(0..n).map(|i|((101+i).to_string(),(201+i).to_string())).collect()};
 let nodes:Vec<_>=(0..n).map(|i|json!({"exchangeId":(101+i).to_string(),"marketId":(201+i).to_string(),"marketTitle":"not a proof","outcome":"YES","currentPrice":null,"role":"member","contractId":format!("contract-{}",101+i)})).collect();
 let canonical=receipt(format!("/relationships?tournamentId={T}&depth=4"),json!({"data":[{"id":R,"type":"mutually_exclusive","source":"admin_tagged","status":"active","label":null,"reason":null,"isExhaustive":exhaustive,"expression":null,"nodes":nodes,"direction":{"kind":"symmetric","fromExchangeIds":[],"toExchangeIds":[],"description":"price metadata"},"constraint":{"description":"not a settlement certificate","priceRule":"sum <= 1","boundSemantics":"price","evaluationEndpoint":"/relationships/constraints"},"createdAt":AT,"updatedAt":AT,"version":2}],"pagination":{"limit":200,"hasMore":false,"nextCursor":null}}));
 let list=relationships::parse_list(&canonical.data,&scope).unwrap();
 let rules:Vec<_>=(0..n).map(|i|receipt(format!("/markets/{}/nodes",201+i),json!({"market_id":(201+i).to_string(),"root":{"node_type":"contract","id":format!("contract-{}",101+i)}}))).collect();
 let cert=SettlementCertificate{version:1,tournament_id:T.into(),relationship_id:R.into(),relationship_version:2,canonical_relationship_sha256:canonical_relationship_sha256(&list.data[0]).unwrap(),relationship_receipt_sha256:receipt_sha256(&canonical).unwrap(),issued_at_ms:now(),expires_at_ms:now()+60_000,verifier_id:"fixture-only-reviewed-rules".into(),logic:CertifiedLogic::MutuallyExclusive{exhaustive},contracts:(0..n).map(|i|ContractCertificate{exchange_id:(101+i).to_string(),market_id:(201+i).to_string(),contract_id:format!("contract-{}",101+i),canonical_outcome:"YES".into(),rule_receipt_sha256:receipt_sha256(&rules[i]).unwrap(),rule_endpoint:rules[i].endpoint.clone(),rule_data_sha256:None,ordinary_yes_payout:"1".into(),ordinary_no_payout:"0".into(),ordinary_no_yes_payout:"0".into(),ordinary_no_no_payout:"1".into(),terminal_rules_complete:true,exceptions:vec![]}).collect()};
 let scope_sha256=format!("{:x}",Sha256::digest(serde_json::to_vec(&scope).unwrap()));
 let census=Census{report:CensusReport{version:1,started_at_ms:now(),completed_at_ms:now(),tournament_id:T.into(),scope_sha256,relationships:Surface{availability:Availability::Available,row_count:Some(1),source:Some(SourceEvidence{receipt_sha256:receipt_sha256(&canonical).unwrap(),private_file:"fixture-private.json".into(),request_started_at:AT.into(),received_at:AT.into(),status:200}),error_code:None,http_status:Some(200),retry_after_ms:None},constraints:surface(),collateral:surface(),account:surface(),graphs:BTreeMap::new(),active_relationship_count:1,exhaustive_relationship_count:usize::from(exhaustive),known_floor_component_count:0,unknown_floor_component_count:0,feed_complete:false,transport_guard_observed:false,execution_authority:false},cache:CensusCache{scope,relationships:Some(list),constraints:None,collateral:None,buying_power:None,graphs:BTreeMap::new(),private_evidence_directory:PathBuf::from("fixture-unused")}};
 let books=(0..n).map(|i|{let e=(101+i).to_string();(e.clone(),Book{exchange_id:e,source:Source{sha256:"b".repeat(64),received_ms:now()},observed_ms:now(),yes_asks:level(if n==3{300_000}else{600_000}),no_asks:level(if n==3{800_000}else if i==0{450_000}else{505_000}),yes_bids:level(290_000),no_bids:level(400_000)})}).collect();
 let policy=Policy{now_ms:now(),max_relationship_age_ms:30_000,max_rule_age_ms:3_600_000,max_book_age_ms:3000,max_book_skew_ms:1000,entry_fee_per_share_per_leg:0,buffer_per_share:5000,minimum_surplus:1,maximum_quantity:100,quantities:vec![10],maximum_retained_candidates:16};
 let capital=Capital{gross_account_cash:100*UNIT,attributed_bank_cash:20*UNIT,reserved_cash:0,maximum_committed_remaining:20*UNIT,package_cost_cap:20*UNIT,orphan_cash_loss_cap:20*UNIT};
 let mut f=Fixture{census,canonical,certs:vec![cert],trusted:BTreeSet::new(),rules,books,policy,capital};f.approve();f
}
// Fixtures above deliberately reproduce only the source-bound minimal adapter
// inputs; no existing test suite is included or rerun through a second module.
fn iso(n:u64)->String{chrono::DateTime::from_timestamp_millis(n as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn v2()->Fixture{let mut f=fixture(2,false);let original=f.canonical.clone();f.certs[0].version=2;f.certs[0].expires_at_ms=now()+120_000;f.certs[0].canonical_relationship_sha256=relationship_semantics_sha256(&f.census.cache.relationships.as_ref().unwrap().data[0]).unwrap();for(i,c)in f.certs[0].contracts.iter_mut().enumerate(){c.rule_data_sha256=Some(rule_data_sha256(&f.rules[i]).unwrap());}f.rules.push(original);f.approve();f}
fn refresh_relation(f:&mut Fixture,at:u64){f.canonical.request_started_at=iso(at);f.canonical.received_at=iso(at);f.census.cache.relationships=Some(relationships::parse_list(&f.canonical.data,&f.census.cache.scope).unwrap());let source=f.census.report.relationships.source.as_mut().unwrap();source.receipt_sha256=receipt_sha256(&f.canonical).unwrap();source.request_started_at=iso(at);source.received_at=iso(at);}
fn advance(f:&mut Fixture,delta:u64){let at=now()+delta;f.policy.now_ms=at;refresh_relation(f,at);let fresh:Vec<_>=f.rules.iter().filter(|r|r.endpoint.starts_with("/markets/")).map(|r|{let mut r=r.clone();r.request_started_at=iso(at);r.received_at=iso(at);r}).collect();f.rules.extend(fresh);for b in f.books.values_mut(){b.source.received_ms=at;b.observed_ms=at;}}
fn assert_blocked(f:&Fixture,reason:&str){let a=f.analyze(&[]);assert!(a.candidates.is_empty());assert_eq!(a.public.blocked_reason_counts.get(reason),Some(&1),"{:?}",a.public.blocked_reason_counts);assert!(!a.public.execution_authority);}
#[test]fn semantic_digest_ignores_only_node_current_price(){let f=fixture(2,false);let row=&f.census.cache.relationships.as_ref().unwrap().data[0];let before=relationship_semantics_sha256(row).unwrap();let mut changed=row.clone();changed.nodes[0].current_price=Some(serde_json::Number::from_f64(0.25).unwrap());assert_ne!(canonical_relationship_sha256(row).unwrap(),canonical_relationship_sha256(&changed).unwrap());assert_eq!(before,relationship_semantics_sha256(&changed).unwrap());for field in ["version","status","expression","direction","constraint","updatedAt","nodes"]{let mut v=serde_json::to_value(row).unwrap();match field{"version"=>v[field]=json!(3),"status"=>v[field]=json!("stale"),"expression"=>v[field]=json!({"kind":"leaf","exchangeId":101}),"direction"=>v[field]["description"]=json!("changed direction meaning"),"constraint"=>v[field]["boundSemantics"]=json!("changed"),"updatedAt"=>v[field]=json!("2026-10-15T09:02:00Z"),_=>v["nodes"][0]["contractId"]=json!("new-contract")};let r=serde_json::from_value(v).unwrap();assert_ne!(before,relationship_semantics_sha256(&r).unwrap(),"{field}");}}
#[test]fn v1_absent_optional_hash_preserves_exact_serialization(){let f=fixture(2,false);let c=&f.certs[0].contracts[0];let v=serde_json::to_value(c).unwrap();assert!(v.get("ruleDataSha256").is_none());let decoded:ContractCertificate=serde_json::from_value(v.clone()).unwrap();assert!(decoded.rule_data_sha256.is_none());assert_eq!(serde_json::to_value(decoded).unwrap(),v);assert_eq!(f.analyze(&[]).candidates.len(),1);}
#[test]fn v1_still_binds_exact_poll_receipt_and_current_price(){let mut f=fixture(2,false);f.policy.now_ms+=1;refresh_relation(&mut f,now()+1);assert_blocked(&f,"STRATEGY_CERTIFICATE_BINDING");let mut f=fixture(2,false);f.canonical.data["data"][0]["nodes"][0]["currentPrice"]=json!(0.3);refresh_relation(&mut f,now());assert_blocked(&f,"STRATEGY_CERTIFICATE_BINDING");}
#[test]fn v2_old_attestation_survives_fresh_polls_and_dynamic_prices(){let mut f=v2();f.policy.max_relationship_age_ms=10000;f.policy.max_rule_age_ms=10000;f.canonical.data["data"][0]["nodes"][0]["currentPrice"]=json!(0.3);advance(&mut f,60000);let a=f.analyze(&[]);assert_eq!(a.public.certified_components,1,"{:?}",a.public.blocked_reason_counts);assert_eq!(a.candidates.len(),1);assert_eq!(a.candidates[0].plan.guaranteed_surplus,400000);assert!(!a.public.execution_authority);let certs=Certificates{values:&f.certs,trusted_sha256:&f.trusted,rule_receipts:&f.rules};let current=validated_rule_receipt(&f.certs[0],&f.certs[0].contracts[0],&certs,&f.census.cache.scope,&f.policy).unwrap();assert_eq!(current.received_at,iso(now()+60000));assert_ne!(receipt_sha256(current).unwrap(),f.certs[0].contracts[0].rule_receipt_sha256);}
#[test]fn v2_requires_original_attestation_exactly_once(){let mut f=v2();f.rules.retain(|r|!r.endpoint.starts_with("/relationships"));assert_blocked(&f,"STRATEGY_RELATIONSHIP_ATTESTATION_MISSING_OR_AMBIGUOUS");let mut f=v2();f.rules.push(f.canonical.clone());assert_blocked(&f,"STRATEGY_RELATIONSHIP_ATTESTATION_MISSING_OR_AMBIGUOUS");}
#[test]fn v2_current_relationship_version_and_semantics_cannot_drift(){for key in ["version","reason","contract","exhaustive","status"]{let mut f=v2();match key{"version"=>f.canonical.data["data"][0]["version"]=json!(3),"reason"=>f.canonical.data["data"][0]["reason"]=json!("new interpretation"),"contract"=>f.canonical.data["data"][0]["nodes"][0]["contractId"]=json!("changed"),"exhaustive"=>f.canonical.data["data"][0]["isExhaustive"]=json!(true),_=>f.canonical.data["data"][0]["status"]=json!("stale")};refresh_relation(&mut f,now());let a=f.analyze(&[]);assert!(a.candidates.is_empty(),"{key}");assert_eq!(a.public.certified_components,0);}}
#[test]fn v2_current_changed_rule_body_blocks_even_with_older_matching_fresh_receipt(){let mut f=v2();advance(&mut f,1000);let r=f.rules.iter_mut().rev().find(|r|r.endpoint=="/markets/201/nodes").unwrap();r.data["opaqueRisk"]=json!({"refund":"new"});assert_blocked(&f,"STRATEGY_RULE_DATA_CHANGED");}
#[test]fn v2_latest_unsuccessful_future_or_unordered_receipt_cannot_hide_behind_old_good(){for case in ["failure","future","request_future"]{let mut f=v2();advance(&mut f,1000);let r=f.rules.iter_mut().rev().find(|r|r.endpoint=="/markets/201/nodes").unwrap();match case{"failure"=>r.status=503,"future"=>r.received_at=iso(now()+1001),_=>r.request_started_at=iso(now()+1001)};assert_blocked(&f,"STRATEGY_RECEIPT_STALE");}}
#[test]fn v2_requires_data_digest_for_every_contract_and_exact_original_body(){let mut f=v2();f.certs[0].contracts[0].rule_data_sha256=None;f.approve();assert_blocked(&f,"STRATEGY_RULE_DATA_HASH_REQUIRED");let mut f=v2();f.certs[0].contracts[0].rule_data_sha256=Some("f".repeat(64));f.approve();assert_blocked(&f,"STRATEGY_RULE_DATA_CHANGED");}
#[test]fn v2_original_attestation_cannot_follow_certificate_issuance(){let mut f=v2();f.certs[0].issued_at_ms=now()-1;f.approve();assert_blocked(&f,"STRATEGY_RELATIONSHIP_ATTESTATION_BINDING");}
#[test]fn v2_current_rules_and_relationships_must_still_be_fresh(){let mut f=v2();f.policy.max_relationship_age_ms=10000;f.policy.now_ms+=10001;assert_blocked(&f,"STRATEGY_RECEIPT_STALE");let mut f=v2();f.policy.max_rule_age_ms=10000;f.policy.now_ms+=10001;refresh_relation(&mut f,now()+10001);assert_blocked(&f,"STRATEGY_RECEIPT_STALE");}
#[test]fn v2_explicit_tournament_rule_query_is_scoped_and_wrong_tournament_denies(){let mut f=v2();for(i,c)in f.certs[0].contracts.iter_mut().enumerate(){f.rules[i].endpoint=format!("{}?tournamentId={T}",f.rules[i].endpoint);c.rule_endpoint=f.rules[i].endpoint.clone();c.rule_receipt_sha256=receipt_sha256(&f.rules[i]).unwrap();}f.approve();advance(&mut f,1000);assert_eq!(f.analyze(&[]).candidates.len(),1);let r=f.rules.iter_mut().rev().find(|r|r.endpoint.starts_with("/markets/201/nodes")).unwrap();r.endpoint="/markets/201/nodes?tournamentId=wrong".into();assert_blocked(&f,"STRATEGY_RULE_TOURNAMENT_SCOPE");}
#[test]fn v2_old_rule_attestation_request_after_received_is_rejected(){let mut f=v2();f.rules[0].request_started_at=iso(now()+1);f.certs[0].contracts[0].rule_receipt_sha256=receipt_sha256(&f.rules[0]).unwrap();f.approve();assert_blocked(&f,"STRATEGY_RULE_ATTESTATION_BINDING");}
#[test]fn v2_original_relationship_pagination_and_scope_are_verified(){for case in ["pagination","tournament"]{let mut f=v2();let r=f.rules.iter_mut().find(|r|r.endpoint.starts_with("/relationships")).unwrap();if case=="pagination"{r.data["pagination"]["hasMore"]=json!(true);r.data["pagination"]["nextCursor"]=json!("next");}else{r.endpoint="/relationships?tournamentId=wrong".into();}f.certs[0].relationship_receipt_sha256=receipt_sha256(r).unwrap();f.approve();assert_blocked(&f,if case=="pagination"{"STRATEGY_RELATIONSHIPS_INCOMPLETE"}else{"STRATEGY_RELATIONSHIP_ATTESTATION_BINDING"});}}
#[test]fn v2_current_relationship_duplicate_tournament_query_is_not_scope_proof(){let mut f=v2();f.canonical.endpoint=format!("/relationships?tournamentId=wrong&tournamentId={T}");refresh_relation(&mut f,now());assert_blocked(&f,"STRATEGY_RELATIONSHIP_RECEIPT_BINDING");}
#[test]fn v2_latest_rule_receipt_ties_are_ambiguous(){let mut f=v2();advance(&mut f,1000);let duplicate=f.rules.iter().rev().find(|r|r.endpoint=="/markets/201/nodes").unwrap().clone();f.rules.push(duplicate);assert_blocked(&f,"STRATEGY_RULE_RECEIPT_MISSING_OR_AMBIGUOUS");}
#[test]fn v2_certificate_expiry_remains_authoritative_after_successful_refresh(){let mut f=v2();advance(&mut f,120000);assert_blocked(&f,"STRATEGY_CERTIFICATE_CLOCK_OR_VERIFIER");}
